class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long pow(long b, long e) {
    long r = 1;
    for (b %= MOD; e > 0; e >>= 1) {
      if ((e & 1) == 1) r = r * b % MOD;
      b = b * b % MOD;
    }
    return r;
  }

  public int xorAfterQueries(int[] nums, int[][] queries) {
    int n = nums.length, B = (int) Math.sqrt(n) + 1;
    long[] a = new long[n];
    for (int i = 0; i < n; i++) a[i] = nums[i];
    long[] inv = new long[100_001];
    boolean[] haveInv = new boolean[100_001];
    int[] head = new int[B + 1], next = new int[queries.length];
    java.util.Arrays.fill(head, -1);
    for (int qi = 0; qi < queries.length; qi++) {
      int l = queries[qi][0], r = queries[qi][1], k = queries[qi][2];
      long v = queries[qi][3];
      if (k >= B) {
        for (int idx = l; idx <= r; idx += k) a[idx] = a[idx] * v % MOD;
      } else {
        next[qi] = head[k];
        head[k] = qi;
      }
    }
    long[] diff = new long[n];
    for (int k = 1; k < B; k++) {
      if (head[k] < 0) continue;
      java.util.Arrays.fill(diff, 1);
      for (int qi = head[k]; qi >= 0; qi = next[qi]) {
        int l = queries[qi][0], r = queries[qi][1], v = queries[qi][3];
        diff[l] = diff[l] * v % MOD;
        int end = l + (r - l) / k * k + k;
        if (end < n) {
          if (!haveInv[v]) {
            inv[v] = pow(v, MOD - 2);
            haveInv[v] = true;
          }
          diff[end] = diff[end] * inv[v] % MOD;
        }
      }
      for (int i = 0; i < n; i++) {
        if (i >= k) diff[i] = diff[i] * diff[i - k] % MOD;
        a[i] = a[i] * diff[i] % MOD;
      }
    }
    int xor = 0;
    for (long v : a) xor ^= (int) v;
    return xor;
  }
}
